-- Plentry: curated ingredient price snapshot (Sainsbury's / Asda / Waitrose)
-- Generated 2026-07-05 from trolley.co.uk own-brand listings (personal one-off research snapshot).
-- Prices are INDICATIVE — captured once for MVP price comparison, not live data.
-- SAFE TO RE-RUN: paste the whole file in Supabase SQL Editor and Run.

create table if not exists public.ingredient_prices (
  id bigint generated always as identity primary key,
  slug text not null,
  display_name text not null,
  category text not null,          -- protein | dairy | veg | fruit | carbs | pantry
  store text not null,             -- sainsburys | asda | waitrose
  meal_key text,                   -- matching key in meals.ing jsonb (null = not in meal catalog yet)
  product_name text not null,
  pack_size text,
  price_gbp numeric not null,
  unit_price text,
  is_estimate boolean default false, -- true = filled by hand, not observed
  captured_on date default now(),
  unique (slug, store)
);

alter table public.ingredient_prices enable row level security;

-- Prices are not sensitive; readable by everyone (incl. logged-out landing page).
drop policy if exists "read ingredient prices" on public.ingredient_prices;
create policy "read ingredient prices" on public.ingredient_prices
  for select using (true);

-- In case the table pre-exists without meal_key (added 5 Jul 2026):
alter table public.ingredient_prices add column if not exists meal_key text;

on conflict (slug, store) do update set
  display_name = excluded.display_name,
  category     = excluded.category,
  meal_key     = excluded.meal_key,
  product_name = excluded.product_name,
  pack_size    = excluded.pack_size,
  price_gbp    = excluded.price_gbp,
  unit_price   = excluded.unit_price,
  is_estimate  = excluded.is_estimate,
  captured_on  = excluded.captured_on;

-- ============ HEALTH CHECK: meal ingredients with missing prices ============
-- Lists every meals.ing key NOT priced at all 4 stores. Should return 0 rows
-- after ingredient_prices_tesco.sql has been applied.
-- Run this after adding new meals to find what needs pricing next.
select k.ing as meal_ingredient, count(p.id) as stores_priced
from (select distinct jsonb_array_elements_text(ing) as ing from public.meals) k
left join public.ingredient_prices p on p.meal_key = k.ing
group by k.ing
having count(p.id) < 4
order by 1;
